<div class="wrap studio-wrap"><h1>Agenda e Google Calendar</h1><div class="studio-panel"><h2>Configurazione Google</h2><form method="post"><?php wp_nonce_field('studio_google');?><div class="studio-form-grid"><div class="studio-field"><label>Client ID</label><input name="client_id" value="<?php echo esc_attr(Studio_DB::get_setting('google_client_id'));?>"></div><div class="studio-field"><label>Client Secret</label><input type="password" name="client_secret" value="<?php echo esc_attr(Studio_DB::get_setting('google_client_secret'));?>"></div><div class="studio-field"><label>Calendar ID</label><input name="calendar_id" value="<?php echo esc_attr(Studio_DB::get_setting('google_calendar_id','primary'));?>"></div></div><p>URI di reindirizzamento da registrare in Google Cloud: <code><?php echo esc_html($this->redirect_uri());?></code></p><button name="studio_google_save" class="button button-primary">Salva</button> <?php if(Studio_DB::get_setting('google_client_id')):?><a class="button" href="<?php echo esc_url($auth);?>"><?php echo $connected?'Ricollega Google Calendar':'Collega Google Calendar';?></a><?php endif;?></form></div><div class="studio-panel"><h2>Nuovo appuntamento</h2><form method="post"><?php wp_nonce_field('studio_appointment');?><input type="hidden" name="studio_appointment" value="1"><div class="studio-form-grid"><div class="studio-field"><label>Paziente</label><select name="paziente_id"><?php foreach($patients as $p):?><option value="<?php echo (int)$p->id;?>"><?php echo esc_html($p->cognome.' '.$p->nome);?></option><?php endforeach;?></select></div><div class="studio-field"><label>Data e ora</label><input type="datetime-local" name="inizio" required></div><div class="studio-field"><label>Durata minuti</label><input type="number" name="durata" value="60"></div><div class="studio-field"><label>Titolo</label><input name="titolo" value="Appuntamento" required></div></div><textarea class="widefat" name="note" placeholder="Note amministrative"></textarea><p><button class="button button-primary">Salva e sincronizza</button></p></form></div><div class="studio-panel"><h2>Appuntamenti</h2><table class="widefat"><thead><tr><th>Data</th><th>Paziente</th><th>Titolo</th><th>Google</th></tr></thead><tbody><?php foreach($events as $e):?><tr><td><?php echo esc_html(date_i18n('d/m/Y H:i',strtotime($e->inizio)));?></td><td><?php echo esc_html($e->cognome.' '.$e->nome);?></td><td><?php echo esc_html($e->titolo);?></td><td><?php echo $e->google_event_id?'Sincronizzato':'Locale';?></td></tr><?php endforeach;?></tbody></table></div></div>
